<template>
  <div>
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/exemptions">Exemption approvals</NuxtLink></li><li>{{ exemption?.title || 'Application' }}</li></ul></div>
    <div v-if="exemption" class="mt-3 space-y-4">
      <section class="card border border-base-200"><div class="card-body"><div class="flex flex-wrap items-start justify-between gap-3"><div><div class="flex items-center gap-2"><h1 class="text-2xl font-bold">{{ exemption.title }}</h1><span class="badge" :class="badge(exemption.status)">{{ format(exemption.status) }}</span></div><p class="text-sm text-base-content/60">{{ exemption.company?.name || 'Procurement entity' }} · APP {{ exemption.plan?.year || '—' }}</p><p v-if="exemption.notes" class="mt-2">{{ Array.isArray(exemption.notes) ? exemption.notes.join(' · ') : exemption.notes }}</p></div><div class="flex flex-wrap gap-2"><button v-for="action in headerActions" :key="action.action || action" class="btn btn-primary btn-sm" @click="openDecision(action.action || action)">{{ format(action.label || action.action || action) }}</button></div></div></div></section>
      <section class="card border border-base-200"><div class="card-body"><h2 class="card-title">Requested exemption items</h2><p class="text-xs text-base-content/60">Scroll horizontally to review all APP fields. Row, Description, UNSPSC and Reference stay frozen.</p><div class="max-h-[65vh] overflow-auto rounded-xl border border-base-300"><table class="exemption-items-grid table table-sm table-zebra"><thead><tr><th>Row</th><th>Description</th><th>UNSPSC</th><th>Reference</th><th>Method</th><th>Group</th><th>Source of funds</th><th>Unit</th><th class="text-right">Quantity</th><th class="text-right">Unit cost</th><th class="text-right">Total</th><th>Quarter</th><th>Expense</th><th>Award type</th><th>Exemption grounds</th><th>Evidence</th><th>APP</th></tr></thead><tbody><tr v-if="!exemption.items?.length"><td colspan="17" class="empty-grid py-12 text-center text-base-content/50">No exemption items were submitted.</td></tr><tr v-for="(item, index) in exemption.items" :key="item.id" class="align-top"><td>{{ index + 1 }}</td><td class="whitespace-pre-wrap">{{ item.description }}</td><td>{{ item.unspsc ? `${item.unspsc.code} · ${item.unspsc.name}` : '—' }}</td><td class="font-mono">{{ item.reference_no || '—' }}</td><td>{{ item.procurementmethod?.name || '—' }}</td><td>{{ item.procurementgroup?.name || '—' }}</td><td>{{ item.sourceoffunds?.name || '—' }}</td><td>{{ item.unitofmeasure?.name || '—' }}</td><td class="text-right">{{ item.quantity }}</td><td class="text-right font-mono">{{ money(item.unit_cost) }}</td><td class="text-right font-mono font-semibold">{{ money(item.total_cost ?? Number(item.quantity || 0) * Number(item.unit_cost || 0)) }}</td><td>{{ item.quarter || '—' }}</td><td>{{ item.expensecategory || '—' }}</td><td>{{ item.award_type === 'FRAMEWORK' ? 'Framework' : 'Award' }}</td><td><div class="min-w-80 space-y-3"><article v-for="ground in item.grounds || []" :key="ground.id || ground.exemption_type_id"><span class="badge badge-outline badge-sm">{{ ground.exemption_type?.name || ground.type_snapshot?.name || 'Exemption' }}</span><p class="mt-1 max-w-lg whitespace-normal text-sm">{{ ground.justification }}</p><dl v-if="Object.keys(ground.requested_terms || {}).length" class="mt-1 grid grid-cols-2 gap-x-3 text-xs text-base-content/60"><template v-for="(value, key) in ground.requested_terms" :key="key"><dt>{{ format(key) }}</dt><dd>{{ value || '—' }}</dd></template></dl></article></div></td><td class="max-w-56 break-all">{{ item.evidence_document_key || '—' }}</td><td>{{ item.promoted_item?.uuid ? 'Added' : 'Pending' }}</td></tr></tbody></table></div></div></section>
      <section v-if="recommendations.length" class="card border border-base-200"><div class="card-body"><h2 class="card-title">Admin recommendations</h2><div class="grid gap-3 md:grid-cols-2"><article v-for="rec in recommendations" :key="rec.id" class="rounded-lg border border-base-200 p-3"><div class="flex justify-between"><strong>Cycle {{ rec.cycle }}</strong><span class="badge" :class="rec.handler_recommendation === 'APPROVE' ? 'badge-success' : 'badge-warning'">{{ format(rec.handler_recommendation) }}</span></div><p class="mt-2 text-sm"><b>Handler:</b> {{ person(rec.handler) }} — {{ rec.handler_comment }}</p><p v-if="rec.manager_action" class="mt-1 text-sm"><b>Reviewer:</b> {{ person(rec.manager) }} — {{ format(rec.manager_action) }}<span v-if="rec.manager_comment"> · {{ rec.manager_comment }}</span></p><p v-if="rec.approver_action" class="mt-1 text-sm"><b>Approver:</b> {{ person(rec.approver) }} — {{ format(rec.approver_action) }}<span v-if="rec.approver_comment"> · {{ rec.approver_comment }}</span></p></article></div></div></section>
      <section class="card border border-base-200"><div class="card-body"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="card-title">Exemptions History</h2><p class="text-sm text-base-content/55">A chronological record of admin comments and decisions.</p></div><span class="badge badge-ghost">{{ adminHistory.length }} update{{ adminHistory.length === 1 ? '' : 's' }}</span></div><div v-if="!adminHistory.length" class="mt-4 rounded-xl border border-dashed border-base-300 py-10 text-center text-sm text-base-content/50"><Icon name="lucide:messages-square" class="mx-auto mb-2 h-7 w-7" />No admin history has been recorded yet.</div><ol v-else class="mt-5 space-y-4"><li v-for="entry in adminHistory" :key="entry.id" class="flex items-start gap-3"><div class="avatar placeholder shrink-0"><div class="w-10 rounded-full bg-primary text-primary-content"><span class="text-sm font-semibold">{{ initials(entry.user || entry.actor) }}</span></div></div><article class="min-w-0 flex-1 rounded-2xl rounded-tl-sm border border-base-200 bg-base-100 shadow-sm"><header class="flex flex-wrap items-start justify-between gap-2 border-b border-base-200 px-4 py-3"><div><p class="font-semibold">{{ person(entry.user || entry.actor) }}</p><p v-if="(entry.user || entry.actor)?.email" class="text-xs text-base-content/50">{{ (entry.user || entry.actor).email }}</p></div><time class="flex items-center gap-1 whitespace-nowrap text-xs text-base-content/50" :datetime="entry.created_at"><Icon name="lucide:clock-3" class="h-3.5 w-3.5" />{{ formatDateTime(entry.created_at) }}</time></header><div class="space-y-3 px-4 py-3"><div class="flex flex-wrap items-center gap-2"><span class="badge badge-primary badge-sm">{{ format(entry.action) }}</span><span class="badge badge-ghost badge-sm">{{ format(entry.from_status) }}</span><Icon name="lucide:arrow-right" class="h-3.5 w-3.5 text-base-content/40" /><span class="badge badge-outline badge-sm">{{ format(entry.to_status) }}</span></div><p v-if="entry.comment" class="whitespace-pre-wrap text-sm leading-6">{{ entry.comment }}</p><p v-else class="text-sm italic text-base-content/45">No comment was added.</p></div></article></li></ol></div></section>
    </div>
    <div v-if="loading" class="flex justify-center py-10"><span class="loading loading-spinner loading-lg" /></div>
    <dialog ref="decisionDialog" class="modal"><div class="modal-box"><h3 class="text-lg font-bold">{{ format(pendingAction) }}</h3><section v-if="latestRecommendation" class="mt-4 overflow-hidden rounded-xl border border-base-300 bg-base-200/40"><header class="flex items-center justify-between border-b border-base-300 px-4 py-3"><div><p class="text-xs font-semibold uppercase tracking-wide text-base-content/50">Previous recommendation</p><p class="text-sm font-semibold">Cycle {{ latestRecommendation.cycle }}</p></div><span :class="['badge', latestRecommendation.handler_recommendation === 'APPROVE' ? 'badge-success' : 'badge-warning']">{{ format(latestRecommendation.handler_recommendation) }}</span></header><div class="divide-y divide-base-300"><article class="px-4 py-3"><div class="flex flex-wrap items-center justify-between gap-2"><p class="text-sm font-semibold">Handler · {{ person(latestRecommendation.handler) }}</p><time class="text-xs text-base-content/45">{{ formatDateTime(latestRecommendation.handler_created_at) }}</time></div><p class="mt-1 whitespace-pre-wrap text-sm leading-5">{{ latestRecommendation.handler_comment || 'No comment was added.' }}</p></article><article v-if="latestRecommendation.manager_action" class="px-4 py-3"><div class="flex flex-wrap items-center justify-between gap-2"><p class="text-sm font-semibold">Reviewer · {{ person(latestRecommendation.manager) }} <span class="badge badge-ghost badge-xs ml-1">{{ format(latestRecommendation.manager_action) }}</span></p><time class="text-xs text-base-content/45">{{ formatDateTime(latestRecommendation.manager_actioned_at) }}</time></div><p class="mt-1 whitespace-pre-wrap text-sm leading-5">{{ latestRecommendation.manager_comment || 'No comment was added.' }}</p></article><article v-if="latestRecommendation.approver_action" class="px-4 py-3"><div class="flex flex-wrap items-center justify-between gap-2"><p class="text-sm font-semibold">Approver · {{ person(latestRecommendation.approver) }} <span class="badge badge-ghost badge-xs ml-1">{{ format(latestRecommendation.approver_action) }}</span></p><time class="text-xs text-base-content/45">{{ formatDateTime(latestRecommendation.approver_actioned_at) }}</time></div><p class="mt-1 whitespace-pre-wrap text-sm leading-5">{{ latestRecommendation.approver_comment || 'No comment was added.' }}</p></article></div></section><label v-if="pendingAction === 'final_decision'" class="fieldset mt-3"><span class="fieldset-legend">Final decision</span><select v-model="selectedFinalAction" class="select w-full"><option value="">Select a decision</option><option v-for="option in finalDecisionOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><p v-if="selectedFinalAction === 'approver_approve'" class="alert alert-info mt-3 text-sm"><Icon name="lucide:info" /> Final approval will add every item to the linked APP as an approved exemption.</p><label v-if="pendingAction === 'handler_recommend'" class="fieldset mt-3"><span class="fieldset-legend">Recommendation</span><select v-model="recommendation" class="select w-full"><option value="">Select recommendation</option><option value="APPROVE">Approve</option><option value="SEND_BACK">Send back to PE</option></select></label><label v-if="pendingAction === 'handler_recommend'" class="fieldset mt-3"><span class="fieldset-legend">Reviewer</span><select v-model.number="selectedUserId" class="select w-full"><option :value="0">Select reviewer</option><option v-for="user in candidates" :key="user.id" :value="user.id">{{ person(user) }}</option></select></label><label v-if="pendingAction === 'manager_agree'" class="fieldset mt-3"><span class="fieldset-legend">Approver</span><select v-model.number="selectedUserId" class="select w-full"><option :value="0">Select approver</option><option v-for="user in candidates" :key="user.id" :value="user.id">{{ person(user) }}</option></select></label><label class="fieldset mt-3"><span class="fieldset-legend">Comment</span><textarea v-model.trim="comment" class="textarea w-full" rows="4" :required="commentRequired" placeholder="Enter the reason for this decision" /></label><p v-if="formError" class="mt-2 text-sm text-error">{{ formError }}</p><div class="modal-action"><button class="btn" @click="decisionDialog.close()">Cancel</button><button class="btn" :class="effectiveAction.includes('send_back') || effectiveAction === 'manager_disagree' ? 'btn-warning' : 'btn-success'" :disabled="saving" @click="decide"><span v-if="saving" class="loading loading-spinner loading-xs" /> Confirm decision</button></div></div></dialog>
  </div>
</template>

<script setup>
definePageMeta({ layout: 'default' });
const route = useRoute();
const api = useExemptionHelper();
const toast = useToast();
const { can } = useCheckPermission();
const exemption = ref(null), actions = ref([]), history = ref([]), recommendations = ref([]), candidates = ref([]), loading = ref(false), saving = ref(false), pendingAction = ref(''), selectedFinalAction = ref(''), comment = ref(''), recommendation = ref(''), selectedUserId = ref(0), formError = ref(''), decisionDialog = ref(null);
const format = value => ({ PENDING_ADMIN_AUTHORIZATION: 'Awaiting handler', PENDING_MANAGER_REVIEW: 'Awaiting reviewer', PENDING_APPROVER_DECISION: 'Awaiting final decision', final_decision: 'Make final decision', approve: 'Submit for admin approval', handler_recommend: 'Handler recommendation', manager_agree: 'Reviewer approve and forward', manager_disagree: 'Reviewer return to handler', approver_approve: 'Approve', approver_send_back_to_manager: 'Return to reviewer', approver_send_back_to_pe: 'Return to PE' }[value] || String(value || '').replaceAll('_', ' ').toLowerCase().replace(/^\w/, c => c.toUpperCase()));
const badge = value => ({ APPROVED: 'badge-success', RETURNED: 'badge-error', PENDING_ADMIN_AUTHORIZATION: 'badge-info', PENDING_MANAGER_REVIEW: 'badge-info', PENDING_APPROVER_DECISION: 'badge-info' }[value] || 'badge-ghost');
const person = user => user ? [user.name, user.lastname].filter(Boolean).join(' ') || user.email : '—';
const initials = user => person(user).split(/\s+/).slice(0, 2).map(part => part[0]?.toUpperCase()).join('') || 'U';
const formatDateTime = value => { if (!value) return 'Date unavailable'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }); };
const effectiveAction = computed(() => pendingAction.value === 'final_decision' ? selectedFinalAction.value : pendingAction.value);
const commentRequired = computed(() => pendingAction.value === 'final_decision' || ['handler_recommend', 'manager_disagree', 'approver_send_back_to_manager', 'approver_send_back_to_pe'].includes(pendingAction.value));
const adminActions = new Set(['handler_recommend', 'manager_agree', 'manager_disagree', 'approver_approve', 'approver_send_back_to_manager', 'approver_send_back_to_pe', 'praz_approve', 'praz_return']);
const adminHistory = computed(() => history.value.filter(entry => adminActions.has(entry.action)));
const latestRecommendation = computed(() => [...recommendations.value].sort((a, b) => Number(b.cycle || 0) - Number(a.cycle || 0))[0] || null);
const reviewActions = new Set(['handler_recommend', 'manager_agree', 'manager_disagree']);
const approvalActions = new Set(['approver_approve', 'approver_send_back_to_manager', 'approver_send_back_to_pe', 'praz_approve', 'praz_return']);
const visibleActions = computed(() => actions.value.filter(action => { const code = action?.action || action; if (reviewActions.has(code)) return can('can.review.adminexemptions'); if (approvalActions.has(code)) return can('can.approve.adminexemptions'); return false; }));
const finalActionCodes = ['approver_approve', 'approver_send_back_to_manager', 'approver_send_back_to_pe'];
const finalDecisionOptions = computed(() => finalActionCodes.filter(code => visibleActions.value.some(action => (action?.action || action) === code)).map(value => ({ value, label: format(value) })));
const headerActions = computed(() => { const ordinary = visibleActions.value.filter(action => !finalActionCodes.includes(action?.action || action)); return finalDecisionOptions.value.length ? [...ordinary, { action: 'final_decision', label: 'Make final decision' }] : ordinary; });
const money = value => Number(value || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const load = async () => { loading.value = true; const [detail, available, transitions, recs] = await Promise.all([api.show(route.params.uuid), api.actions(route.params.uuid), api.transitions(route.params.uuid), api.recommendations(route.params.uuid)]); loading.value = false; if (detail.error) { toast.error({ title: 'Error', message: detail.error.data?.message || 'Could not load this application.', position: 'topRight', layout: 2 }); return; } exemption.value = detail.data?.data; actions.value = available.data?.data?.actions ?? available.data?.data ?? []; history.value = transitions.data?.data ?? []; recommendations.value = recs.data?.data ?? []; };
const openDecision = async action => { pendingAction.value = action; selectedFinalAction.value = ''; comment.value = ''; recommendation.value = ''; selectedUserId.value = 0; formError.value = ''; candidates.value = []; decisionDialog.value.showModal(); const stage = action === 'handler_recommend' ? 'manager' : action === 'manager_agree' ? 'approver' : null; if (stage) { const result = await api.eligibleNextActors(route.params.uuid, stage); candidates.value = result.data?.data ?? []; } };
const decide = async () => { formError.value = ''; const action = effectiveAction.value; if (pendingAction.value === 'final_decision' && !action) { formError.value = 'Select the final decision.'; return; } if (commentRequired.value && !comment.value) { formError.value = 'A comment is required for this decision.'; return; } if (pendingAction.value === 'handler_recommend' && (!recommendation.value || !selectedUserId.value)) { formError.value = 'Select a recommendation and reviewer.'; return; } if (pendingAction.value === 'manager_agree' && !selectedUserId.value) { formError.value = 'Select the approver.'; return; } const extra = pendingAction.value === 'handler_recommend' ? { recommendation: recommendation.value, manager_user_id: selectedUserId.value } : pendingAction.value === 'manager_agree' ? { approver_user_id: selectedUserId.value } : {}; saving.value = true; const { data, error } = await api.transition(route.params.uuid, action, comment.value || null, extra); saving.value = false; if (error || data?.status === false) { toast.error({ title: 'Decision failed', message: error?.data?.message || data?.message || 'The decision could not be saved.', position: 'topRight', layout: 2 }); return; } toast.success({ title: 'Decision saved', message: data.message || 'The exemption workflow was updated.', position: 'topRight', layout: 2 }); decisionDialog.value.close(); await load(); };
onMounted(load);
</script>

<style scoped>
.exemption-items-grid { width: max-content; min-width: 100%; border-collapse: separate; border-spacing: 0; }
.exemption-items-grid th { position: sticky; top: 0; z-index: 2; white-space: nowrap; background: var(--color-base-200); }
.exemption-items-grid tr > :nth-child(1) { --column-width: 4rem; --column-left: 0rem; }
.exemption-items-grid tr > :nth-child(2) { --column-width: 16rem; --column-left: 4rem; }
.exemption-items-grid tr > :nth-child(3) { --column-width: 14rem; --column-left: 20rem; }
.exemption-items-grid tr > :nth-child(4) { --column-width: 10rem; --column-left: 34rem; }
.exemption-items-grid tr > :nth-child(-n + 4):not(.empty-grid) { position: sticky; left: var(--column-left); z-index: 3; box-sizing: border-box; width: var(--column-width); min-width: var(--column-width); max-width: var(--column-width); background: var(--color-base-100); overflow-wrap: anywhere; }
.exemption-items-grid thead tr > :nth-child(-n + 4) { z-index: 4; background: var(--color-base-200); }
.exemption-items-grid tr > :nth-child(4) { border-right: 2px solid var(--color-base-300); }
</style>
